fn oracle_utf16b_60_60_n() {
    check(
        b"\xff\xfe<\x00t\x00e\x00s\x00t\x00s\x00u\x00i\x00t\x00e\x00 \x00n\x00a\x00m\x00e\x00=\x00\"\x00s\x00\"\x00>\x00<\x00t\x00e\x00s\x00t\x00c\x00a\x00s\x00e\x00 \x00n\x00a\x00m\x00e\x00=\x00\"\x00a\x00\"\x00/\x00>\x00\x0a\x00 \x00 \x00 \x00 \x00 \x00 \x00 \x00<\x00/\x00t\x00e\x00s\x00t\x00s\x00u\x00i\x00t\x00e\x00>\x00 ",
        None,
    );
}

